    /// <summary>
    /// Builds this program's modules and reflection. The reflection is parsed once here,
    /// not re-derived from source at runtime.
    /// </summary>
    public static apos_shapesProgram Create() => new(
        VertexSpirv,
        PixelSpirv,
        new ShaderReflection
        {
            Uniforms = new UniformParam[]
            {
                new("view_projection", 0, 64, UniformType.Matrix4x4),
                new("half_viewport", 64, 8, UniformType.Vector2),
                new("dither_scale", 72, 4, UniformType.Float),
                new("dither_mode", 76, 4, UniformType.Float),
                new("ramp_texel", 80, 8, UniformType.Vector2),
                new("band_tex_size", 88, 8, UniformType.Vector2),
                new("band_texel", 96, 8, UniformType.Vector2),
                new("curve_texel", 104, 8, UniformType.Vector2),
            },
            Textures = new ResourceBinding[]
            {
                new("TextureTex", 0),
                new("BandTex", 1),
                new("CurveTex", 2),
                new("ArcTex", 3),
                new("BlueNoiseTex", 4),
                new("RampTex", 5),
            },
            Samplers = new ResourceBinding[]
            {
                new("TextureSampler", 0),
                new("BandSampler", 1),
                new("CurveSampler", 2),
                new("ArcSampler", 3),
                new("BlueNoiseSampler", 4),
                new("RampSampler", 5),
            },
        }
    );

    /// <summary>Resolves this program's uniform slots against a built pipeline's reflection.</summary>
    public readonly struct apos_shapesParameters
    {
        internal apos_shapesParameters(ShaderReflection reflection)
        {
            view_projection = SlotOf(reflection, "view_projection");
            half_viewport = SlotOf(reflection, "half_viewport");
            dither_scale = SlotOf(reflection, "dither_scale");
            dither_mode = SlotOf(reflection, "dither_mode");
            ramp_texel = SlotOf(reflection, "ramp_texel");
            band_tex_size = SlotOf(reflection, "band_tex_size");
            band_texel = SlotOf(reflection, "band_texel");
            curve_texel = SlotOf(reflection, "curve_texel");
        }

        public int view_projection { get; }
        public int half_viewport { get; }
        public int dither_scale { get; }
        public int dither_mode { get; }
        public int ramp_texel { get; }
        public int band_tex_size { get; }
        public int band_texel { get; }
        public int curve_texel { get; }

        private static int SlotOf(ShaderReflection reflection, string name)
        {
            foreach (var uniform in reflection.Uniforms)
            {
                if (uniform.Name == name) return uniform.Offset;
            }
            return -1;
        }
    }

    public sealed record apos_shapesProgram(ReadOnlyMemory<byte> Vertex, ReadOnlyMemory<byte> Pixel, ShaderReflection Reflection)
    {
        public apos_shapesParameters Bind() => new(Reflection);
    }
}
